def comprimir_repeticiones(texto: str) -> str:
    if not texto:
        return ""

    resultado = []
    contador = 1

    for i in range(1, len(texto)):
        if texto[i] == texto[i - 1]:
            contador += 1
        else:
            resultado.append(texto[i - 1])
            resultado.append(str(contador))
            contador = 1

    # Agregar el último grupo
    resultado.append(texto[-1])
    resultado.append(str(contador))

    return "".join(resultado)

def iniciales(nombre: str) -> str:
    palabras = nombre.split()
    return ''.join(palabra[0].upper() for palabra in palabras)

def aplanar(datos: list) -> list:
    resultado = []
    for elemento in datos:
        if isinstance(elemento, (list, tuple)):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

import csv
from io import StringIO
from typing import List, Dict

def parsear_ventas(texto: str) -> list[dict]:
    if not texto or not texto.strip():
        return []

    reader = csv.reader(StringIO(texto))

    # Obtener la cabecera
    try:
        headers = next(reader)
    except StopIteration:
        return []  # Texto vacío o solo whitespace

    expected_header = ["fecha", "producto", "cantidad", "precio"]
    if headers != expected_header:
        raise ValueError("La cabecera no es la indicada")

    result: List[Dict[str, object]] = []

    for row in reader:
        # Ignorar líneas vacías o que solo contengan espacios
        if not row or all(cell.strip() == "" for cell in row):
            continue

        # Cada fila debe tener exactamente 4 campos
        if len(row) != 4:
            raise ValueError("Una fila no tiene exactamente 4 campos")

        fecha, producto, cantidad_str, precio_str = row

        # Validar y convertir cantidad (entero no negativo)
        try:
            cantidad = int(cantidad_str)
        except ValueError:
            raise ValueError("cantidad no es un entero")

        if cantidad < 0:
            raise ValueError("cantidad no puede ser negativa")

        # Validar y convertir precio (número flotante)
        try:
            precio = float(precio_str)
        except ValueError:
            raise ValueError("precio no es un número")

        result.append({
            "fecha": fecha,
            "producto": producto,
            "cantidad": cantidad,
            "precio": precio
        })

    return result

from datetime import datetime

def parsear_fecha(texto: str) -> str:
    # Eliminar espacios al principio y final
    texto = texto.strip()

    # Mapeo de meses en español (minúsculas para búsqueda insensible)
    months = {
        "enero": 1, "febrero": 2, "marzo": 3, "abril": 4,
        "mayo": 5, "junio": 6, "julio": 7, "agosto": 8,
        "septiembre": 9, "octubre": 10, "noviembre": 11, "diciembre": 12
    }

    # Formato 1: AAAA-MM-DD (YYYY-MM-DD)
    try:
        dt = datetime.strptime(texto, "%Y-%m-%d")
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        pass

    # Formato 2: DD/MM/AAAA (DD/MM/YYYY)
    try:
        dt = datetime.strptime(texto, "%d/%m/%Y")
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        pass

    # Formato 3: D de MES de AAAA
    parts = texto.split()

    if len(parts) != 5:
        raise ValueError("Formato no reconocido")

    # El último elemento debe ser el año (4 dígitos)
    try:
        year = int(parts[-1])
    except ValueError:
        raise ValueError("Año debe tener 4 dígitos")

    # El segundo a último debe ser un mes válido
    if parts[-2] not in months:
        raise ValueError(f"Mes no reconocido: {parts[-2]}")

    # El primer elemento es el día (1 o 2 dígitos)
    try:
        day = int(parts[0])
    except ValueError:
        raise ValueError("Día debe ser un número")

    # Crear y validar la fecha
    dt = datetime(day, months[parts[-2]], year)

    return dt.strftime("%Y-%m-%d")

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado

from collections import OrderedDict


class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad <= 0:
            raise ValueError("La capacidad debe ser un entero positivo")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave not in self._datos:
            return None
        # Mover al final para marcar como usado recientemente
        self._datos.move_to_end(clave)
        return self._datos[clave]

    def put(self, clave, valor):
        if clave in self._datos:
            # Actualizar y mover al final
            self._datos[clave] = valor
            self._datos.move_to_end(clave)
        elif len(self._datos) >= self.capacidad:
            # Eliminar la más antigua (primera en el OrderedDict)
            self._datos.popitem(last=False)

    def __len__(self):
        return len(self._datos)
